diff --git a/services/crow/pkg/client/client.go b/services/crow/pkg/client/client.go
index 724664e..880ec67 100644
--- a/services/crow/pkg/client/client.go
+++ b/services/crow/pkg/client/client.go
@@ -132,3 +132,53 @@ func (c *Client) ListVersions(ctx context.Context, id api.ModuleIdentifier) ([]s
 		return nil, fmt.Errorf("unexpected status %d listing %s", resp.StatusCode, id.VersionsPath())
 	}
 }
+
+// Download fetches the gzipped tarball bytes for the given module
+// version. It follows the X-Terraform-Get redirect returned by Crow's
+// 204 response (per the Terraform module registry protocol). The caller
+// is responsible for closing the returned ReadCloser.
+//
+// Returns ErrNotFound on HTTP 404 from Crow.
+func (c *Client) Download(ctx context.Context, m api.Module) (io.ReadCloser, error) {
+	if err := m.Validate(); err != nil {
+		return nil, err
+	}
+	req, err := http.NewRequestWithContext(ctx, http.MethodGet, c.baseURL+m.DownloadPath(), nil)
+	if err != nil {
+		return nil, err
+	}
+	resp, err := c.httpClient.Do(req)
+	if err != nil {
+		return nil, err
+	}
+
+	// The protocol uses 204 + X-Terraform-Get to point clients at the
+	// real artifact location (S3 presigned URL in production).
+	if resp.StatusCode == http.StatusNotFound {
+		_ = resp.Body.Close()
+		return nil, ErrNotFound
+	}
+	if resp.StatusCode != http.StatusNoContent && resp.StatusCode != http.StatusOK {
+		_ = resp.Body.Close()
+		return nil, fmt.Errorf("unexpected status %d resolving %s", resp.StatusCode, m.DownloadPath())
+	}
+	location := resp.Header.Get("X-Terraform-Get")
+	_ = resp.Body.Close()
+	if location == "" {
+		return nil, fmt.Errorf("crow returned %d with no X-Terraform-Get header for %s", resp.StatusCode, m.DownloadPath())
+	}
+
+	blobReq, err := http.NewRequestWithContext(ctx, http.MethodGet, location, nil)
+	if err != nil {
+		return nil, err
+	}
+	blobResp, err := c.httpClient.Do(blobReq)
+	if err != nil {
+		return nil, fmt.Errorf("fetching presigned blob: %w", err)
+	}
+	if blobResp.StatusCode != http.StatusOK {
+		_ = blobResp.Body.Close()
+		return nil, fmt.Errorf("unexpected status %d fetching blob %s", blobResp.StatusCode, location)
+	}
+	return blobResp.Body, nil
+}
