@@ -189,3 +189,67 @@ func TestListVersionsEmptyModulesIsNotFound(t *testing.T) {
 		t.Fatalf("expected ErrNotFound, got %v", err)
 	}
 }
+
+func TestDownloadOK(t *testing.T) {
+	mux := http.NewServeMux()
+	// Tarball server: serves the actual gzipped bytes.
+	tarball := []byte("fake-tarball-bytes")
+	tarSrv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		if r.URL.Path != "/blob/iac/comply/aws/1.0.0.tar.gz" {
+			t.Errorf("tarball server got unexpected path: %s", r.URL.Path)
+		}
+		_, _ = w.Write(tarball)
+	}))
+	defer tarSrv.Close()
+
+	// Crow server: returns 204 + X-Terraform-Get pointing at tarSrv.
+	mux.HandleFunc("/v1/modules/iac/comply/aws/1.0.0/download", func(w http.ResponseWriter, r *http.Request) {
+		if r.Method != http.MethodGet {
+			t.Errorf("expected GET, got %s", r.Method)
+		}
+		w.Header().Set("X-Terraform-Get", tarSrv.URL+"/blob/iac/comply/aws/1.0.0.tar.gz")
+		w.WriteHeader(http.StatusNoContent)
+	})
+	crowSrv := httptest.NewServer(mux)
+	defer crowSrv.Close()
+
+	cli := New(crowSrv.URL, WithHTTPClient(crowSrv.Client()))
+	rc, err := cli.Download(context.Background(), testModule())
+	if err != nil {
+		t.Fatalf("Download: %v", err)
+	}
+	defer rc.Close()
+	got, err := io.ReadAll(rc)
+	if err != nil {
+		t.Fatalf("read: %v", err)
+	}
+	if !bytes.Equal(got, tarball) {
+		t.Errorf("body = %q, want %q", got, tarball)
+	}
+}
+
+func TestDownloadNotFound(t *testing.T) {
+	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
+		w.WriteHeader(http.StatusNotFound)
+	}))
+	defer srv.Close()
+
+	cli := New(srv.URL, WithHTTPClient(srv.Client()))
+	_, err := cli.Download(context.Background(), testModule())
+	if !errors.Is(err, ErrNotFound) {
+		t.Fatalf("expected ErrNotFound, got %v", err)
+	}
+}
+
+func TestDownloadMissingHeader(t *testing.T) {
+	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
+		w.WriteHeader(http.StatusNoContent) // no X-Terraform-Get header
+	}))
+	defer srv.Close()
+
+	cli := New(srv.URL, WithHTTPClient(srv.Client()))
+	_, err := cli.Download(context.Background(), testModule())
+	if err == nil {
+		t.Fatal("expected error for missing X-Terraform-Get header")
+	}
+}
